    41	
    42	  it("Can serve asset (GET)", async () => {
    43	    const res = await t.fetch("/test.png", {
    44	      headers: {
    45	        "if-none-match": "w/456",
    46	        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
    47	        "accept-encoding": "gzip, br",
    48	      },
    49	    });
    50	
    51	    expect(res.status).toEqual(200);
    52	    expect(await res.text()).toBe("asset:/test.png.gz");
    53	    expect(Object.fromEntries(res.headers)).toMatchObject(expectedHeaders);
    54	    expect(res.headers.get("content-length")).toBe("18");
    55	  });
    56	
    57	  it("Can serve asset (HEAD)", async () => {
    58	    const headRes = await t.fetch("/test.png", {
    59	      method: "HEAD",
    60	      headers: {
    61	        "if-none-match": "w/456",
    62	        "if-modified-since": new Date(1_700_000_000_000 - 1).toUTCString(),
    63	        "accept-encoding": "gzip, br",
    64	      },
