   132	    }
   133	  });
   134	
   135	  it("Matches encodings with q-values and any case", async () => {
   136	    for (const [acceptEncoding, expected] of [
   137	      ["gzip;q=1.0", "asset:/test.png.gz"],
   138	      ["GZIP", "asset:/test.png.gz"],
   139	      ["br ; q=1", "asset:/test.png.br"],
   140	      // Preferred by weight, not by header order.
   141	      ["gzip;q=0.5, br;q=0.8", "asset:/test.png.br"],
   142	      // Equal weights keep header order.
   143	      ["br, gzip", "asset:/test.png.br"],
   144	      // `q=0` means "not acceptable".
   145	      ["gzip;q=0, br;q=0.000", "asset:/test.png"],
   146	      ["gzip;q=0", "asset:/test.png"],
   147	      // A coding with an unparsable weight is dropped (identity is always safe).
   148	      ["gzip;q=0invalid, br;q=0.5", "asset:/test.png.br"],
   149	      ["gzip;q=0.0001", "asset:/test.png"],
   150	      ["gzip;q=-1", "asset:/test.png"],
   151	      ['gzip;q="0"', "asset:/test.png"],
   152	      ["br;q=0.001, gzip;q=0.0010", "asset:/test.png.br"],
   153	      // `x-gzip` is an alias of `gzip`.
   154	      ["X-GZIP", "asset:/test.png.gz"],
   155	      // `*` matches any coding not listed explicitly.
   156	      ["*", "asset:/test.png.gz"],
   157	      ["gzip;q=0, *", "asset:/test.png.br"],
   158	      ["br;q=0.5, *;q=0.8", "asset:/test.png.gz"],
   159	      ["*;q=0", "asset:/test.png"],
   160	      // Explicitly listed codings win ties with `*` matches.
   161	      ["*, br", "asset:/test.png.br"],
   162	      // The first occurrence of a coding wins.
   163	      ["gzip;q=0, gzip", "asset:/test.png"],
   164	    ]) {
   165	      const res = await t.fetch("/test.png", {
   166	        headers: { "accept-encoding": acceptEncoding! },
   167	      });
   168	      expect(await res.text(), acceptEncoding).toBe(expected);
   169	    }
   170	  });
   171	
   172	  it("Ignores inherited object keys in accept-encoding", async () => {
   173	    const res = await t.fetch("/test.png", {
   174	      headers: { "accept-encoding": "constructor, __proto__, toString" },
   175	    });
