   219	  it("Returns 404 if not found", async () => {
   220	    const res = await t.fetch("/404/test.png");
   221	    expect(res.status).toEqual(404);
   222	
   223	    const headRes = await t.fetch("/404/test.png", { method: "HEAD" });
   224	    expect(headRes.status).toEqual(404);
   225	  });
   226	
   227	  it("Handles cache (if-modified-since) for sub-second mtime", async () => {
   228	    // mtime with millisecond precision. The `last-modified` header the server
   229	    // emits is truncated to whole seconds (HTTP-date granularity), so a client
   230	    // echoing that exact value in `if-modified-since` must still get a 304.
   231	    const subSecondOptions: ServeStaticOptions = {
   232	      getContents: vi.fn((id) => `asset:${id}`),
   233	      getMeta: vi.fn((id) => ({
   234	        type: "text/plain",
   235	        mtime: 1_700_000_000_500, // 500ms past the whole second
   236	        path: id,
   237	        size: `asset:${id}`.length,
